    # Step 2: 8-rows replace zeros
    for rr, zz in rows_with_8:
        for c in zz:
            output[rr][c] = 2

    # Step 3: Process gaps BETWEEN 8-rows
    for i in range(len(rows_with_8)-1):
        r1, zeros1 = rows_with_8[i]
        r2, zeros2 = rows_with_8[i+1]

        gap_rows = list(range(r1 + 1, r2))
        gap_size = len(gap_rows)

        all_gap_zeros = set(zeros1) | set(zeros2)
        all_gap_cols = sorted(all_gap_zeros)
        min_col = min(all_gap_cols)
        max_col = max(all_gap_cols)

        for j, r in enumerate(gap_rows):
            pos_in_gap = j

            if gap_size == 1:
                # Single gap: MIN-MAX horizontal fill
                for c in range(min_col, max_col + 1):
                    if output[r][c] == 0:
                        output[r][c] = 2
            else:
